def build_shock_rows():
    rows = ''
    for _, r in top_shocks.iterrows():
        direction = '&#9650;' if r['MoM_Change'] > 0 else '&#9660;'
        color = '#1a8a7d' if r['MoM_Change'] > 0 else '#c75c4a'
        rows += f'''<tr>
            <td>{r["Date"].strftime("%b %Y")}</td>
            <td>${r["Crude_Oil_Price"]:.2f}</td>
            <td style="color:{color};font-weight:600">{direction} ${r["MoM_Change"]:+.2f}</td>
            <td style="color:{color};font-weight:600">{r["MoM_Pct_Change"]:+.1f}%</td>
        </tr>'''
    return rows

def build_yoy_rows():
    rows = ''
    for _, r in top_yoy.iterrows():
        direction = '&#9650;' if r['YoY_Pct'] > 0 else '&#9660;'
        color = '#1a8a7d' if r['YoY_Pct'] > 0 else '#c75c4a'
        rows += f'''<tr>
            <td>{int(r["Year"])}</td>
            <td>${r["Avg_Price"]:.2f}</td>
            <td style="color:{color};font-weight:600">{direction} ${r["YoY_Change"]:+.2f}</td>
            <td style="color:{color};font-weight:600">{r["YoY_Pct"]:+.1f}%</td>
        </tr>'''
    return rows

def build_decade_rows():
    rows = ''
    for d in decade_order:
        s = decade_stats.loc[d]
        rows += f'''<tr>
            <td style="font-weight:600">{d}</td>
            <td>${s["Mean"]:.2f}</td>
            <td>${s["Median"]:.2f}</td>
            <td>${s["Std"]:.2f}</td>
            <td>${s["Min"]:.2f}</td>
            <td>${s["Max"]:.2f}</td>
            <td>{int(s["Count"])}</td>
        </tr>'''
    return rows

def build_decade_sections():
    sections = ''
    for d in decade_order:
        label = d
        key = d  # e.g. '1970s'
        s = decade_stats.loc[d]
        narrative = decade_narratives.get(key, '')
        sections += f'''
        <div class="decade-card">
            <h4>{label}</h4>
            <p>{narrative}</p>
            <div class="decade-stats-row">
                <span><strong>Mean:</strong> ${s["Mean"]:.2f}</span>
                <span><strong>Std Dev:</strong> ${s["Std"]:.2f}</span>
                <span><strong>Range:</strong> ${s["Min"]:.2f} – ${s["Max"]:.2f}</span>
                <span><strong>Observations:</strong> {int(s["Count"])}</span>
            </div>
        </div>'''
    return sections

