    --navy: #1a2744;
    --teal: #1a8a7d;
    --steel: #4a6fa5;
    --amber: #d4a843;
    --coral: #c75c4a;
    --slate: #5c6b7a;
    --bg: #f4f5f7;
    --card-bg: #ffffff;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, 'Helvetica Neue', Arial, sans-serif;
    background: var(--bg);
    color: #2c3e50;
    line-height: 1.65;
  }}
  .report-header {{
    background: linear-gradient(135deg, var(--navy) 0%, #2a4a7f 100%);
    color: white;
    padding: 50px 40px 40px;
    text-align: center;
  }}
  .report-header h1 {{
    font-size: 2.2em;
    font-weight: 700;
    margin-bottom: 10px;
    letter-spacing: -0.5px;
  }}
  .report-header .subtitle {{
    font-size: 1.1em;
    color: #a8c4e0;
    font-weight: 300;
  }}
  .report-header .meta {{
    margin-top: 18px;
    font-size: 0.85em;
    color: #7fa8cc;
  }}
  .container {{
    max-width: 1200px;
    margin: 0 auto;
    padding: 30px 24px;
  }}
  .section {{
    background: var(--card-bg);
    border-radius: 10px;
